create or replace view IDQ_PRODUCTION.EKS_CALCULATION.SRMARA_EKS_ITEM_ZACTIVE_ZISRELEVANTBYASSOCIATIONEABA_UPDSEL(
	ITEMID,
	ZACTIVE,
	ZACTIVENEW,
	ZISRELEVANTBYASSOCIATION,
	ZISRELEVANTBYASSOCIATIONNEW
) as
SELECT distinct   stMARA_EKS_ITEM_1.ITEMID,          stMARA_EKS_ITEM_1.zActive,          EKS_CALCULATION.STMARA_EKS_ITEM.zActive AS zActiveNew,          stMARA_EKS_ITEM_1.zIsRelevantByAssociation,          1                           AS zIsRelevantByAssociationNew   FROM   EKS_CALCULATION.STMARA_EKS_ITEM          INNER JOIN EKS.ITEMSORTING                  ON EKS_CALCULATION.STMARA_EKS_ITEM.ITEMID = EKS.ITEMSORTING.ITEMID          INNER JOIN EKS_CALCULATION.STMARA_EKS_ITEM AS stMARA_EKS_ITEM_1                  ON EKS.ITEMSORTING.SORTITEMID = stMARA_EKS_ITEM_1.ITEMID   WHERE  ( EKS_CALCULATION.STMARA_EKS_ITEM.BITFLAG = '0' )          AND ( stMARA_EKS_ITEM_1.BITFLAG = '2' )          AND ( EKS_CALCULATION.STMARA_EKS_ITEM.zActive = 1 )          AND ( EKS_CALCULATION.STMARA_EKS_ITEM.zIsCurrentContract = 1 )          AND ( IFNULL(stMARA_EKS_ITEM_1.zForceNotRelevant,0) = 0 )  ;